test('asset.fromAttachment copies admitted pixels into a new Design dependency under the original selection scope',async()=>{const f=fixture(),r=regionFixture(f),upload=await f.ctx.fileUploads.uploadImageStream({sessionId:'designer-p-one',data:(async function*(){yield r.bytes})(),mediaType:'image/png'}),result=await admitWorkbenchAI(f.owner,input({target:{projectId:'p-one',pageId:'a-one',scope:'selection'},selection:{selector:'#buy'},attachments:[upload]}),undefined,policy,{user:true}),agent=f.agents.get(result.sessionId),task=f.owner.aiWorkbench.taskFor(agent),saved=await f.owner.aiWorkbench.assetFromAttachment({attachmentId:upload.image.attachmentId,expectedRevision:f.project.revision,name:'illustration'},{agent,task,policy});assert.match(saved.file.path,/^designs\/main\/assets\/r-/);assert.equal(saved.file.mimeType,'image/png');assert.deepEqual(f.binaryFiles.get('/project/projects/p-one/'+saved.file.path),r.bytes);assert.equal(f.calls.find(c=>c.assetImport)?.target.scope,'selection');assert.equal(f.calls.find(c=>c.assetImport)?.immutableDependency,true);await assert.rejects(f.owner.aiWorkbench.assetFromAttachment({attachmentId:'image-foreign',expectedRevision:f.project.revision},{agent,task,policy}),code('REFERENCE_NOT_FOUND'));await assert.rejects(f.owner.aiWorkbench.assetFromAttachment({attachmentId:upload.image.attachmentId},{agent,task:{...task,scope:'read'},policy}),code('SCOPE_DENIED'));});
test('source-only task gets exact per-operation source file policy and cannot modify unrelated project objects',async()=>{const f=fixture(),target=sourceFixture(f),parent={mode:'danger-full-access',workspaceRoot:'/project'};f.owner.policy=()=>parent;const result=await admitWorkbenchAI(f.owner,input({mode:'edit',target,sourceWrite:{sourceProjectId:'r-source',paths:['src'],authorization:{kind:'forged'}}}),undefined,parent,{user:true}),agent=f.agents.get(result.sessionId),task=f.owner.aiWorkbench.taskFor(agent);assert.deepEqual(task.pageIds,[]);assert.deepEqual(task.designIds,[]);assert.deepEqual(task.allowedPaths,[]);assert.deepEqual(task.sourceWrite.paths,['src/App.tsx']);assert.equal(task.sourceWrite.authorization.kind,'user-source-write');const authority=await f.owner.aiWorkbench.authorizeAction({action:'file.write',projectId:'p-one',content:'code',expectedVersion:'doc-v1'},{agent,task,policy});assert.equal(authority.input.sourceId,'r-source');assert.equal(authority.input.path,'src/App.tsx');assert.equal(authority.policy.mode,'workspace-write');assert.deepEqual(authority.policy.additionalWritableRoots,['/source/src/App.tsx']);assert.equal(policy.additionalWritableRoots,undefined);assert.throws(()=>f.owner.aiWorkbench.assertAction({action:'page.create',projectId:'p-one',designId:'d-one'},{task}),code('SCOPE_DENIED'));await assert.rejects(f.owner.aiWorkbench.authorizeAction({action:'file.write',projectId:'p-one',sourceId:'r-source',path:'src/Other.tsx'},{agent,task,policy}),code('SCOPE_DENIED'));});
