test('source permission is re-resolved from its original native parent Session instead of the global default',async()=>{const f=fixture(),target=sourceFixture(f),parent={mode:'danger-full-access',workspaceRoot:'/project',sessionId:'main'};let current=parent;f.agents.set('main',{id:'main',session:{snapshotEvents:()=>[]}});f.owner.policy=agent=>agent?.id==='main'?current:policy;const result=await admitWorkbenchAI(f.owner,input({mode:'edit',target,sourceWrite:{sourceProjectId:'r-source',paths:['src/App.tsx']}}),undefined,parent,{user:true}),agent=f.agents.get(result.sessionId),task=f.owner.aiWorkbench.taskFor(agent),request={action:'file.write',projectId:'p-one',sourceId:'r-source',path:'src/App.tsx'};assert.equal(task.sourceWrite.authorization.permissionSessionId,'main');assert.deepEqual((await f.owner.aiWorkbench.authorizeAction(request,{agent,task,policy})).policy.additionalWritableRoots,['/source/src/App.tsx']);current={...parent,mode:'read-only'};await assert.rejects(f.owner.aiWorkbench.authorizeAction(request,{agent,task,policy}),code('SCOPE_DENIED'));assert.ok(f.calls.includes('resolveAgent:main'));});
